func:
// Recebe o JSON publicado pelo app17-11 em FIAPIoT/motor/multiclasse.
// No MQTT-in em datatype "json" o payload ja chega como objeto; protegemos
// mesmo assim contra string.
let p = msg.payload;
if (typeof p === "string") {
    try { p = JSON.parse(p); }
    catch (e) { node.error("Payload nao e JSON valido", msg); return null; }
}

// classe vem da SEQUENCIA CICLICA do proprio ESP32 (nao ha botao aqui).
const classe = p.classe || "desconhecida";
// rodada identifica a VOLTA completa pela sequencia -- e o group do
// LeaveOneGroupOut no notebook 2.6, por isso vira tag (como label na Forma 1
// binaria), nao field.
const rodada = String(p.rodada != null ? p.rodada : "00");

// As 12 features (item 3 do plano: as 7 originais + 5 novas sobre a
// magnitude) + janela (indice dentro da rodada) + fs_real (taxa medida).
const fields = {
    janela:    Number(p.janela),
    fs_real:   Number(p.fs_real),
    mean_ax:   Number(p.mean_ax),
    mean_ay:   Number(p.mean_ay),
    mean_az:   Number(p.mean_az),
    std_ax:    Number(p.std_ax),
    std_ay:    Number(p.std_ay),
    std_az:    Number(p.std_az),
    rms_mag:   Number(p.rms_mag),
    std_mag:   Number(p.std_mag),
    p2p_mag:   Number(p.p2p_mag),
    crest_mag: Number(p.crest_mag),
    kurt_mag:  Number(p.kurt_mag),
    zcr_mag:   Number(p.zcr_mag)
};

// classe e rodada como TAGS: e o que o notebook 2.6 usa pra agrupar
// (groupby classe/rodada) e pro LeaveOneGroupOut por rodada.
const tags = {
    classe: classe,
    rodada: rodada,
    device: p.device || "esp32"
};

node.status({ fill: "green", shape: "dot",
    text: classe + " r" + rodada + " | fs_real=" + (isFinite(fields.fs_real) ? fields.fs_real.toFixed(0) : "?") });

// node-red-contrib-influxdb: payload = [fields, tags]
msg.payload = [fields, tags];
return msg;
